import { useState } from "react";
import "./styles/AdminP.css"; // Cambio en el nombre del archivo CSS
import { useNavigate } from "react-router-dom";

function AdminP({ users, user, onBack }) {
  const [showEditModal, setShowEditModal] = useState(false);
  const [editingUser, setEditingUser] = useState(null);
  const [usersList, setUsersList] = useState(users || []);
  const navigate = useNavigate();

  const handleEditClick = (userData) => {
    setEditingUser({ ...userData });
    setShowEditModal(true);
  };

  const handleCloseModal = () => {
    setShowEditModal(false);
    setEditingUser(null);
  };

  const handleSaveUser = (e) => {
    e.preventDefault();
    setUsersList(
      usersList.map((u) =>
        u.username === editingUser.username ? editingUser : u
      )
    );
    handleCloseModal();
  };

  const handleDeleteUser = (username) => {
    setUsersList(usersList.filter((u) => u.username !== username));
  };

  const handleAddUser = () => {
    const newUser = {
      name: "",
      username: `user${usersList.length + 1}`,
      role: "",
      email: "",
    };
    setEditingUser(newUser);
    setShowEditModal(true);
  };

  const handleBack = () => {
    navigate(-1); // Regresa a la página anterior
  };

  return (
    <div className="adminP-container">
      {/* Header */}
      <header className="adminP-header">
        <div className="adminP-header-left">
          {/* Botón de regresar */}
          <button className="adminP-back-btn" onClick={handleBack} title="Volver">
            <i className="bi bi-chevron-double-left"></i>
          </button>
          <h1 className="adminP-title">TalkinPon</h1>
        </div>

        {/* Icono de usuario */}
        <div className="adminP-user-icon-container">
          <i className="bi bi-person-circle user-icon"></i>
          <h5>Super Administrador</h5>
        </div>
      </header>

      {/* Main */}
      <main className="adminP-main">
        <div className="adminP-section">
          <h2 className="adminP-section-header">Gestión de Usuarios</h2>

          <table className="adminP-table">
            <thead>
              <tr>
                <th>Nombre del procesos</th>
                <th>Descripcion</th>
                <th>Requisitos</th>
                <th>Dependecia</th>
                <th>Opciones</th>
              </tr>
            </thead>
            <tbody>
              {usersList.map((u) => (
                <tr key={u.username}>
                  <td>{u.name}</td>
                  <td>{u.username}</td>
                  <td>{u.role}</td>
                  <td>{u.email}</td>
                  <td>
                    <button className="adminP-option-btn edit" onClick={() => handleEditClick(u)} title="Editar">
                      <i className="bi bi-pencil-fill"></i>
                    </button>
                    <button className="adminP-option-btn delete" onClick={() => handleDeleteUser(u.username)} title="Eliminar">
                      <i className="bi bi-trash-fill"></i>
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          <div className="adminP-add-user-container">
            <button className="adminP-add-user-btn" onClick={handleAddUser}>
              Agregar nuevo usuario
            </button>
          </div>
        </div>
      </main>

      {/* Modal */}
      {showEditModal && editingUser && (
        <div className="adminP-modal-overlay" onClick={handleCloseModal}>
          <div className="adminP-modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="adminP-modal-header">
              <h2>
                {editingUser.username.startsWith("user")
                  ? "Agregar Usuario"
                  : "Editar Usuario"}
              </h2>
              <button className="adminP-modal-close" onClick={handleCloseModal}>
                ✕
              </button>
            </div>
            <form className="adminP-edit-form" onSubmit={handleSaveUser}>
              <div className="form-group">
                <label>Nombre:</label>
                <input
                  type="text"
                  value={editingUser.name}
                  onChange={(e) => setEditingUser({ ...editingUser, name: e.target.value })}
                  placeholder="Nombre completo"
                  required
                />
              </div>
              <div className="adminP-form-group">
                <label>Usuario:</label>
                <input
                  type="text"
                  value={editingUser.username}
                  onChange={(e) => setEditingUser({ ...editingUser, username: e.target.value })}
                  placeholder="Nombre de usuario"
                  required
                />
              </div>
              <div className="adminP-form-group">
                <label>Rol:</label>
                <input
                  type="text"
                  value={editingUser.role}
                  onChange={(e) => setEditingUser({ ...editingUser, role: e.target.value })}
                  placeholder="Rol del usuario"
                  required
                />
              </div>
              <div className="adminP-form-group">
                <label>Email:</label>
                <input
                  type="email"
                  value={editingUser.email}
                  onChange={(e) => setEditingUser({ ...editingUser, email: e.target.value })}
                  placeholder="Email"
                  required
                />
              </div>
              <div className="adminP-form-actions">
                <button type="button" className="adminP-btn-cancel" onClick={handleCloseModal}>
                  Cancelar
                </button>
                <button type="submit" className="adminP-btn-save">
                  Guardar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default AdminP;
